/* CSS PART 1 OF 2 */

/* DESIGN TOKENS */
:root {
  --ink: #202c30;
  --ink-soft: #536166;
  --paper: #f7f6f2;
  --surface: #ffffff;
  --forest: #263f3b;
  --forest-deep: #192f2c;
  --copper: #bd754d;
  --copper-light: #e7b18e;
  --line: #deded7;
  --muted: #888e89;

  --font-heading: "DM Serif Display", Georgia, serif;
  --font-body: "DM Sans", Arial, sans-serif;

  --container: 1160px;
  --gutter: clamp(22px, 5.5vw, 76px);
  --header-height: 88px;

  --radius: 3px;
  --shadow: 0 16px 50px rgba(25, 47, 44, 0.12);
  --transition: 220ms ease;
}

/* RESET */
* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 105px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select,
textarea {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--copper);
  outline-offset: 4px;
}

::selection {
  background: var(--copper-light);
  color: var(--ink);
}

/* SHARED TYPOGRAPHY */
h1,
h2,
h3,
h4 {
  margin: 0;
  color: var(--ink);
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -0.025em;
}

h1 {
  font-size: clamp(3.2rem, 7.2vw, 6.5rem);
}

h2 {
  font-size: clamp(2.5rem, 4.8vw, 4.2rem);
}

h3 {
  font-size: clamp(1.55rem, 2.4vw, 2rem);
}

p {
  margin: 0 0 1.25rem;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--copper);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.19em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 1px;
  background: currentColor;
  content: "";
}

.section-intro {
  max-width: 620px;
  color: var(--ink-soft);
  font-size: 1.05rem;
  line-height: 1.85;
}

.section-heading {
  max-width: 760px;
  margin-bottom: 24px;
}

.text-accent {
  color: var(--copper);
}

.container {
  width: min(100% - var(--gutter) * 2, var(--container));
  margin-inline: auto;
}

.section {
  padding-block: clamp(76px, 10vw, 132px);
}

.section--light {
  background: var(--surface);
}

.section--dark {
  background: var(--forest);
  color: #edf0e9;
}

.section--dark h2,
.section--dark h3 {
  color: #fff;
}

.section--dark .section-intro {
  color: #d1d9d2;
}

/* ANNOUNCEMENT / HEADER */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--surface);
  border-bottom: 1px solid rgba(32, 44, 48, 0.09);
}

.header-inner {
  display: flex;
  width: min(100% - var(--gutter) * 2, 1320px);
  min-height: var(--header-height);
  margin-inline: auto;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.brand {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 14px;
}

.brand-logo {
  width: 66px;
  height: 66px;
  flex: 0 0 auto;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.brand-name {
  color: var(--forest-deep);
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  line-height: 1.2;
}

.brand-descriptor {
  color: var(--muted);
  font-size: 0.63rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  line-height: 1.4;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: clamp(20px, 3vw, 38px);
}

.primary-nav a:not(.button) {
  position: relative;
  color: var(--ink-soft);
  font-size: 0.82rem;
  font-weight: 700;
  transition: color var(--transition);
}

.primary-nav a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: -8px;
  left: 0;
  height: 2px;
  background: var(--copper);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.primary-nav a:not(.button):hover {
  color: var(--forest);
}

.primary-nav a:not(.button):hover::after {
  transform: scaleX(1);
}

/* BUTTONS */
.button {
  display: inline-flex;
  min-height: 52px;
  padding: 14px 24px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--copper);
  color: #fff;
  cursor: pointer;
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.075em;
  line-height: 1.3;
  text-align: center;
  text-transform: uppercase;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  transform: translateY(-2px);
  background: #a65e39;
}

.button--light {
  background: var(--surface);
  color: var(--forest-deep);
}

.button--light:hover {
  background: var(--copper-light);
  color: var(--ink);
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: #fff;
}

.button--outline:hover {
  border-color: #fff;
  background: #fff;
  color: var(--forest-deep);
}

.button-arrow {
  font-size: 1.15rem;
  line-height: 1;
}

/* FULL-BLEED HERO */
.hero {
  position: relative;
  display: flex;
  min-height: min(780px, calc(100svh - var(--header-height)));
  min-height: clamp(600px, 78vw, 780px);
  align-items: center;
  overflow: hidden;
  background: var(--forest-deep);
  color: #fff;
  isolation: isolate;
}

.hero-media {
  position: absolute;
  z-index: -2;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(18, 36, 33, 0.91) 0%,
      rgba(18, 36, 33, 0.75) 43%,
      rgba(18, 36, 33, 0.25) 100%
    ),
    linear-gradient(
      0deg,
      rgba(18, 36, 33, 0.34),
      transparent 45%
    );
  content: "";
}

.hero-content {
  width: min(100% - var(--gutter) * 2, var(--container));
  margin: 0 auto;
  padding-block: 100px;
}

.hero .eyebrow {
  color: var(--copper-light);
}

.hero h1 {
  max-width: 850px;
  margin-bottom: 26px;
  color: #fff;
}

.hero-description {
  max-width: 580px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, 0.88);
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  line-height: 1.85;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.hero-location {
  display: flex;
  margin-top: 54px;
  align-items: center;
  gap: 13px;
  color: rgba(255, 255, 255, 0.82);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.hero-location::before {
  width: 35px;
  height: 1px;
  background: var(--copper-light);
  content: "";
}

/* EXPERIENCE / COMPANY INTRODUCTION */
.intro-layout {
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  align-items: center;
  gap: clamp(48px, 8vw, 110px);
}

.intro-copy {
  max-width: 550px;
}

.intro-copy h2 {
  margin-bottom: 26px;
}

.intro-copy p {
  color: var(--ink-soft);
}

.intro-visual {
  position: relative;
  min-height: 390px;
}

.intro-visual img {
  width: 100%;
  height: 450px;
  object-fit: cover;
  object-position: center;
}

.experience-note {
  position: absolute;
  right: -22px;
  bottom: -25px;
  width: 185px;
  padding: 25px 22px;
  background: var(--forest);
  color: #fff;
  box-shadow: var(--shadow);
}

.experience-number {
  display: block;
  color: var(--copper-light);
  font-family: var(--font-heading);
  font-size: 3.5rem;
  line-height: 1;
}

.experience-label {
  display: block;
  margin-top: 10px;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  line-height: 1.6;
  text-transform: uppercase;
}

/* OPERATING APPROACH */
.approach-header {
  display: flex;
  margin-bottom: 56px;
  align-items: end;
  justify-content: space-between;
  gap: 40px;
}

.approach-header .section-heading {
  margin-bottom: 0;
}

.approach-header .section-intro {
  max-width: 400px;
}

.approach-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-top: 1px solid rgba(255, 255, 255, 0.24);
}

.approach-item {
  display: flex;
  min-height: 190px;
  padding: 35px 36px 35px 0;
  align-items: flex-start;
  gap: 25px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.24);
}

.approach-item:nth-child(odd) {
  border-right: 1px solid rgba(255, 255, 255, 0.24);
}

.approach-item:nth-child(even) {
  padding-left: 36px;
}

.approach-number {
  color: var(--copper-light);
  font-family: var(--font-heading);
  font-size: 1.8rem;
  line-height: 1.2;
}

.approach-item h3 {
  margin-bottom: 12px;
  font-size: 1.6rem;
}

.approach-item p {
  max-width: 400px;
  margin: 0;
  color: #d1d9d2;
  font-size: 0.92rem;
}

/* ROOFING / HAIL RESTORATION */
.roofing-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: center;
  gap: clamp(48px, 8vw, 100px);
}

.roofing-copy h2 {
  margin-bottom: 24px;
}

.roofing-copy p {
  color: var(--ink-soft);
}

.roofing-image {
  position: relative;
  min-height: 500px;
  overflow: hidden;
  background: #e4e2dc;
}

.roofing-image img {
  width: 100%;
  height: 500px;
  object-fit: cover;
  object-position: center 55%;
  transition: transform 600ms ease;
}

.roofing-image:hover img {
  transform: scale(1.025);
}

.roofing-caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 26px 30px;
  background: linear-gradient(transparent, rgba(20, 35, 32, 0.88));
  color: #fff;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* ROOFING GUIDE */
.guide-section {
  background: #eeede7;
}

.guide-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  align-items: start;
  gap: clamp(45px, 8vw, 100px);
}

.guide-heading {
  position: sticky;
  top: 35px;
}

.guide-heading h2 {
  margin-bottom: 22px;
}

.guide-heading p {
  color: var(--ink-soft);
}

.guide-steps {
  border-top: 1px solid var(--line);
}

.guide-step {
  display: grid;
  grid-template-columns: 60px 1fr;
  padding-block: 28px;
  gap: 22px;
  border-bottom: 1px solid var(--line);
}

.guide-step-number {
  color: var(--copper);
  font-family: var(--font-heading);
  font-size: 2rem;
  line-height: 1.2;
}

.guide-step h3 {
  margin-bottom: 9px;
  font-size: 1.55rem;
}

.guide-step p {
  margin: 0;
  color: var(--ink-soft);
  font-size: 0.94rem;
}

/* RECENT PROJECTS */
.projects-header {
  display: flex;
  margin-bottom: 48px;
  align-items: end;
  justify-content: space-between;
  gap: 32px;
}

.projects-header .section-heading {
  margin-bottom: 0;
}

.projects-layout {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  grid-template-rows: 270px 270px;
  gap: 18px;
}

.project {
  position: relative;
  min-width: 0;
  overflow: hidden;
  background: #d9d9d2;
}

.project--large {
  grid-row: 1 / 3;
}

.project img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 600ms ease;
}

.project:hover img {
  transform: scale(1.04);
}

.project::after {
  position: absolute;
  inset: 35% 0 0;
  background: linear-gradient(transparent, rgba(20, 35, 32, 0.84));
  content: "";
  pointer-events: none;
}

.project-caption {
  position: absolute;
  z-index: 1;
  right: 25px;
  bottom: 22px;
  left: 25px;
  color: #fff;
}

.project-caption span {
  display: block;
  margin-bottom: 5px;
  color: var(--copper-light);
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.project-caption h3 {
  color: #fff;
  font-family: var(--font-body);
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: 0;
}
