/* CSS PART 2 OF 2 */

/* CONTACT / CONVERSION */
.contact-section {
  position: relative;
  overflow: hidden;
  background: var(--forest-deep);
  color: #fff;
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(45px, 8vw, 110px);
}

.contact-copy h2 {
  margin-bottom: 24px;
  color: #fff;
}

.contact-copy > p {
  max-width: 450px;
  color: #d1d9d2;
}

.contact-detail {
  display: flex;
  margin-top: 36px;
  align-items: center;
  gap: 14px;
  color: var(--copper-light);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.contact-detail::before {
  width: 30px;
  height: 1px;
  background: currentColor;
  content: "";
}

.contact-form {
  padding: clamp(25px, 4vw, 48px);
  background: var(--surface);
  color: var(--ink);
  box-shadow: var(--shadow);
}

.contact-form h3 {
  margin-bottom: 10px;
  font-size: 2rem;
}

.form-intro {
  margin-bottom: 28px;
  color: var(--ink-soft);
  font-size: 0.9rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--ink);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.035em;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-height: 50px;
  padding: 12px 14px;
  border: 1px solid #d8dad4;
  border-radius: 2px;
  background: #fbfbf9;
  color: var(--ink);
  transition: border-color var(--transition), background var(--transition);
}

.form-field textarea {
  min-height: 125px;
  resize: vertical;
}

.form-field input:hover,
.form-field select:hover,
.form-field textarea:hover {
  border-color: var(--forest);
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--copper);
  background: #fff;
}

.form-submit {
  width: 100%;
  margin-top: 24px;
}

.form-note {
  margin: 13px 0 0;
  color: var(--muted);
  font-size: 0.75rem;
  line-height: 1.6;
}

/* FOOTER */
.site-footer {
  padding-block: 42px;
  background: #142622;
  color: #d1d9d2;
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.footer-brand img {
  width: 48px;
  height: 48px;
  object-fit: contain;
}

.footer-brand-name {
  color: #fff;
  font-size: 0.82rem;
  font-weight: 800;
}

.footer-copy {
  margin: 0;
  color: #aab8af;
  font-size: 0.75rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
}

.footer-links a {
  color: #d1d9d2;
  font-size: 0.76rem;
  font-weight: 700;
  transition: color var(--transition);
}

.footer-links a:hover {
  color: var(--copper-light);
}

/* ACCESSIBLE MOBILE MENU CONTROL */
.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  padding: 0;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: transparent;
  color: var(--forest);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* RESPONSIVE: TABLET */
@media (max-width: 900px) {
  :root {
    --header-height: 76px;
  }

  .header-inner {
    gap: 16px;
  }

  .brand-logo {
    width: 56px;
    height: 56px;
  }

  .brand-name {
    font-size: 0.84rem;
  }

  .primary-nav {
    gap: 16px;
  }

  .primary-nav a:not(.button) {
    font-size: 0.74rem;
  }

  .primary-nav .button {
    padding-inline: 15px;
    font-size: 0.69rem;
  }

  .intro-layout,
  .roofing-layout,
  .guide-layout,
  .contact-layout {
    grid-template-columns: 1fr 1fr;
    gap: 40px;
  }

  .intro-visual img {
    height: 380px;
  }

  .experience-note {
    right: -10px;
  }

  .projects-layout {
    grid-template-rows: 230px 230px;
  }

  .approach-header {
    align-items: flex-start;
    flex-direction: column;
    gap: 20px;
  }

  .guide-heading {
    position: static;
  }

  .contact-form {
    padding: 28px;
  }

  .footer-inner {
    flex-wrap: wrap;
  }
}

/* RESPONSIVE: MOBILE NAVIGATION */
@media (max-width: 680px) {
  :root {
    --gutter: 22px;
    --header-height: 72px;
  }

  html {
    scroll-padding-top: 82px;
  }

  .header-inner {
    position: relative;
    min-height: var(--header-height);
  }

  .brand {
    gap: 9px;
  }

  .brand-logo {
    width: 49px;
    height: 49px;
  }

  .brand-name {
    max-width: 205px;
    font-size: 0.79rem;
  }

  .brand-descriptor {
    font-size: 0.56rem;
  }

  .menu-toggle {
    display: flex;
    flex: 0 0 46px;
  }

  .primary-nav {
    position: absolute;
    top: calc(100% - 1px);
    right: calc(var(--gutter) * -1);
    left: calc(var(--gutter) * -1);
    display: none;
    max-height: calc(100svh - var(--header-height));
    padding: 18px var(--gutter) 25px;
    overflow-y: auto;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    border-top: 1px solid var(--line);
    background: var(--surface);
    box-shadow: 0 16px 24px rgba(25, 47, 44, 0.12);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a:not(.button) {
    display: block;
    padding: 13px 0;
    border-bottom: 1px solid var(--line);
    color: var(--ink);
    font-size: 0.88rem;
  }

  .primary-nav a:not(.button)::after {
    display: none;
  }

  .primary-nav .button {
    width: 100%;
    margin-top: 16px;
  }

  /* MOBILE SHARED LAYOUT */
  .section {
    padding-block: 76px;
  }

  h1 {
    font-size: clamp(3rem, 12vw, 4.6rem);
  }

  h2 {
    font-size: clamp(2.35rem, 9vw, 3.3rem);
  }

  .section-intro {
    font-size: 0.96rem;
  }

  /* MOBILE HERO */
  .hero {
    min-height: 690px;
    min-height: min(760px, 88svh);
    align-items: flex-end;
  }

  .hero-media {
    object-position: 61% center;
  }

  .hero::before {
    background:
      linear-gradient(
        0deg,
        rgba(18, 36, 33, 0.94) 0%,
        rgba(18, 36, 33, 0.79) 48%,
        rgba(18, 36, 33, 0.2) 100%
      );
  }

  .hero-content {
    padding-block: 65px 54px;
  }

  .hero h1 {
    max-width: 600px;
  }

  .hero-description {
    max-width: 480px;
    font-size: 0.96rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-location {
    margin-top: 30px;
    font-size: 0.65rem;
  }

  /* MOBILE INTRO */
  .intro-layout,
  .roofing-layout,
  .guide-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 42px;
  }

  .intro-visual {
    min-height: 0;
    margin-right: 12px;
  }

  .intro-visual img {
    height: 330px;
  }

  .experience-note {
    right: -12px;
    bottom: -20px;
    width: 145px;
    padding: 19px;
  }

  .experience-number {
    font-size: 2.8rem;
  }

  .experience-label {
    font-size: 0.6rem;
  }

  /* MOBILE APPROACH */
  .approach-header {
    margin-bottom: 32px;
  }

  .approach-layout {
    grid-template-columns: 1fr;
  }

  .approach-item,
  .approach-item:nth-child(even) {
    min-height: auto;
    padding: 26px 0;
    border-right: 0;
  }

  .approach-item h3 {
    font-size: 1.4rem;
  }

  /* MOBILE ROOFING */
  .roofing-image,
  .roofing-image img {
